import tomllib
from dataclasses import dataclass
from pathlib import Path

SETTINGS_FILE = Path("settings.toml")


@dataclass
class Settings:
    game_dir: Path | None = None  # game install folder, the one containing Levels/
    levels_dir: Path = Path("Levels")  # stock .stream files that mods are built from

    def to_toml(self) -> str:
        game_dir = f"'{self.game_dir.as_posix()}'" if self.game_dir else "''"
        return (
            "# Generated by `madkit config`. Machine-specific, not tracked by git.\n\n"
            "# Game install folder (the one containing Levels/), used by `madkit mod install`\n"
            f"game_dir = {game_dir}\n\n"
            "# Stock .stream files that mods are built from\n"
            f"levels_dir = '{self.levels_dir.as_posix()}'\n"
        )


def load_settings() -> Settings:
    if not SETTINGS_FILE.is_file():
        return Settings()
    with open(SETTINGS_FILE, "rb") as f:
        data = tomllib.load(f)
    settings = Settings()
    if data.get("game_dir"):
        settings.game_dir = Path(data["game_dir"])
    if data.get("levels_dir"):
        settings.levels_dir = Path(data["levels_dir"])
    return settings


def save_settings(settings: Settings) -> None:
    SETTINGS_FILE.write_text(settings.to_toml())
